import React,{useEffect,useState} from 'react';
const initial={name:'',phone:'',email:'',weddingDate:'',visitDate:'',visitTime:'',dress:'',people:1,message:'',privacy:false,marketing:false};
export default function ReservationForm(){const [form,setForm]=useState(initial);const [state,setState]=useState('idle');const [notice,setNotice]=useState('');useEffect(()=>{const s=localStorage.getItem('selectedDress');if(s)setForm(f=>({...f,dress:s}))},[]);const change=e=>{const {name,value,type,checked}=e.target;setForm(f=>({...f,[name]:type==='checkbox'?checked:value}))};const validate=()=>{if(!form.name.trim())return'이름을 입력해주세요.';if(!/^01[016789]-?\d{3,4}-?\d{4}$/.test(form.phone.trim()))return'연락처를 정확하게 입력해주세요.';if(!form.weddingDate)return'결혼 예정일을 선택해주세요.';if(!form.visitDate)return'방문 희망일을 선택해주세요.';if(!form.visitTime)return'방문 시간을 선택해주세요.';if(!form.privacy)return'개인정보 수집 및 이용에 동의해주세요.';return''};const submit=async e=>{e.preventDefault();const err=validate();if(err){setNotice(err);setState('error');return}const endpoint=process.env.REACT_APP_GOOGLE_SCRIPT_URL||'https://script.google.com/macros/s/AKfycbzzaaE11mH__fdtF5syKiBJB8RJilQIUDChTgTD5xns6ZSOZYlXOO91Se4JFK-O_McB/exec';setState('loading');setNotice('');try{const payload={...form,submittedAt:new Date().toISOString(),status:'신규신청'};const res=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'text/plain;charset=utf-8'},body:JSON.stringify(payload)});const text=await res.text();const result=JSON.parse(text);if(result.status!=='success')throw new Error(result.message||'저장 실패');setState('success');setNotice('예약 신청이 완료되었습니다. 담당자가 확인 후 예약 확정 안내를 드립니다.');setForm(initial);localStorage.removeItem('selectedDress')}catch(error){console.error('Reservation error:',error);setState('error');setNotice('예약 처리 중 문제가 발생했습니다. Apps Script 웹앱 권한과 웨딩예약 시트를 확인해주세요.')}};const min=new Date().toISOString().split('T')[0];return <section className="section reservation" id="reservation"><div className="inner reserve-grid"><div className="reserve-copy"><span className="eyebrow">RESERVATION</span><h2>YOUR PERFECT<br/>DRESS AWAITS.</h2><p>원하시는 날짜와 시간을 남겨주시면 담당자가 확인 후 예약 확정 연락을 드립니다.</p></div><form className="reserve-form" onSubmit={submit}><div className="two"><label>이름 *<input name="name" value={form.name} onChange={change} placeholder="홍길동"/></label><label>연락처 *<input name="phone" value={form.phone} onChange={change} placeholder="010-1234-5678"/></label></div><label>이메일<input type="email" name="email" value={form.email} onChange={change} placeholder="hello@example.com"/></label><div className="two"><label>결혼 예정일 *<input type="date" min={min} name="weddingDate" value={form.weddingDate} onChange={change}/></label><label>방문 희망일 *<input type="date" min={min} name="visitDate" value={form.visitDate} onChange={change}/></label></div><div className="two"><label>방문 희망시간 *<select name="visitTime" value={form.visitTime} onChange={change}><option value="">선택해주세요</option>{['10:00','11:00','12:00','13:00','14:00','15:00','16:00','17:00'].map(t=><option key={t}>{t}</option>)}</select></label><label>방문 인원 *<input type="number" min="1" max="6" name="people" value={form.people} onChange={change}/></label></div><label>관심 드레스<select name="dress" value={form.dress} onChange={change}><option value="">선택해주세요</option>{Array.from({length:8},(_,i)=>`ÉCLAT 0${i+1}`).map(d=><option key={d}>{d}</option>)}</select></label><label>요청사항<textarea name="message" value={form.message} onChange={change} placeholder="피팅 관련 요청사항을 남겨주세요."/></label><label className="check"><input type="checkbox" name="privacy" checked={form.privacy} onChange={change}/> 개인정보 수집 및 이용에 동의합니다. [필수]</label><label className="check"><input type="checkbox" name="marketing" checked={form.marketing} onChange={change}/> 마케팅 정보 수신에 동의합니다. [선택]</label>{notice&&<p className={`notice ${state}`}>{notice}</p>}<button className="submit" disabled={state==='loading'}>{state==='loading'?'예약 접수 중...':'피팅 예약 신청하기'}</button></form></div></section>}
