import React,{useState} from 'react';
const dresses=[
 {name:'ÉCLAT 01',cat:'SIGNATURE',img:'dress01.png'}, {name:'ÉCLAT 02',cat:'CLASSIC',img:'dress02.png'}, {name:'ÉCLAT 03',cat:'MODERN',img:'dress03.png'}, {name:'ÉCLAT 04',cat:'ROMANTIC',img:'dress04.png'},
 {name:'ÉCLAT 05',cat:'SIGNATURE',img:'dress05.png'}, {name:'ÉCLAT 06',cat:'CLASSIC',img:'dress06.png'}, {name:'ÉCLAT 07',cat:'MODERN',img:'dress07.png'}, {name:'ÉCLAT 08',cat:'ROMANTIC',img:'dress08.png'}
];
export default function Collection(){const [filter,setFilter]=useState('ALL');const cats=['ALL','SIGNATURE','CLASSIC','MODERN','ROMANTIC'];const items=filter==='ALL'?dresses:dresses.filter(d=>d.cat===filter);const reserve=d=>{localStorage.setItem('selectedDress',d.name);document.getElementById('reservation')?.scrollIntoView({behavior:'smooth'})};return <section className="section soft" id="collection"><div className="inner"><span className="eyebrow">BRIDAL COLLECTION</span><div className="section-head"><h2>드레스를 고르는 순간부터<br/>설레도록.</h2><div className="filters">{cats.map(c=><button className={filter===c?'active':''} onClick={()=>setFilter(c)} key={c}>{c}</button>)}</div></div><div className="dress-grid">{items.map(d=><article className="dress-card" key={d.name}><div className="dress-img"><img src={process.env.PUBLIC_URL+'/images/'+d.img} alt={d.name}/><div className="dress-overlay"><button onClick={()=>reserve(d)}>이 드레스 피팅 예약하기</button></div></div><span>{d.cat}</span><h3>{d.name}</h3></article>)}</div></div></section>}
