import React,{useState} from 'react';
export default function LookBook(){const [open,setOpen]=useState(null);const imgs=['look01.png','look02.png','look03.png','look04.png'];return <section className="section soft" id="lookbook"><div className="inner"><span className="eyebrow">LOOK BOOK</span><h2>한 장의 화보처럼<br/>기억될 순간</h2><div className="look-grid">{imgs.map((im,i)=><button onClick={()=>setOpen(im)} key={im} className={`look-item item-${i+1}`}><img src={process.env.PUBLIC_URL+'/images/'+im} alt={`룩북 ${i+1}`}/></button>)}</div></div>{open&&<div className="lightbox" onClick={()=>setOpen(null)}><button aria-label="닫기">×</button><img src={process.env.PUBLIC_URL+'/images/'+open} alt="확대된 룩북"/></div>}</section>}
